def find_pattern(n, m, filenames, indices):
    # Convert indices to 0-based
    indices = [i - 1 for i in indices]

    # Initialize the pattern with the first file to be deleted
    pattern = list(filenames[indices[0]])

    # Iterate over the remaining files to be deleted
    for index in indices[1:]:
        current_file = filenames[index]
        for i in range(len(pattern)):
            if pattern[i] != current_file[i]:
                pattern[i] = '?'

    # Check if the pattern matches exactly m files
    def matches(filename, pattern):
        if len(filename) != len(pattern):
            return False
        for f, p in zip(filename, pattern):
            if p != '?' and f != p:
                return False
        return True

    count = sum(1 for filename in filenames if matches(filename, pattern))

    if count == m:
        return "Yes", "".join(pattern)
    else:
        return "No", ""

